courseData.forEach(mod=>mod.lessons.forEach(lesson=>{const d=window.V26_DETAILS[lesson.id];if(!d)return;lesson.content=`<section class="v26-depth"><div class="depth-meter"><strong>Deep Learning Path</strong><span>Foundation → Mechanism → Clinical Application → Registry Discrimination</span></div><h3>Foundation</h3><p>${d.principle}</p><h3>How it works</h3><p>${d.mechanism}</p><h3>Clinical / image connection</h3><p>${d.clinical}</p><div class="lesson-callout"><strong>Registry trap:</strong> ${d.trap}</div><h3>Active review</h3><p>Use the animation and interactive controls above, then mark the lesson reviewed. The five-question check below is not a pass gate; it is used to update your mastery profile.</p></section>`;lesson.narration=[d.principle,d.mechanism,d.clinical,d.trap].join(" ");lesson.check=d.questions;}));

