const v26CircuitQuestions=[
 {q:'After line compensation, which component is most directly associated with selecting the voltage delivered to the primary side of the high-voltage transformer?',options:['Autotransformer','Filament step-down transformer','Rectifier bank','Rotor'],answer:0,rationale:'The autotransformer uses selectable taps to provide variable primary voltage and is associated with kVp selection.'},
 {q:'The exposure switch closes and the selected primary voltage has passed the timing/control stage. Where does the high-voltage pathway go next?',options:['High-voltage step-up transformer','Filament transformer','Focusing cup','Stator'],answer:0,rationale:'The step-up transformer raises the selected primary voltage to the kilovoltage range used across the tube.'},
 {q:'Which component changes low-voltage, higher-current filament power rather than producing the tube kilovoltage?',options:['Step-down filament transformer','High-voltage transformer','Autotransformer','Rectifiers'],answer:0,rationale:'The filament transformer steps voltage down and current up to heat the tungsten filament.'},
 {q:'A generator produces the correct kVp selection but the filament does not heat. Which circuit should be investigated first?',options:['Filament circuit','High-voltage rectifier circuit only','Rotor circuit only','Image receptor circuit'],answer:0,rationale:'Filament heating depends on the separate low-voltage, high-current filament circuit.'},
 {q:'What is the primary purpose of rectification in the x-ray generator?',options:['Maintain tube polarity so electron flow is cathode to anode','Increase filament current','Select focal spot size','Rotate the anode'],answer:0,rationale:'Rectifiers prevent reverse tube current and maintain the required polarity across the tube.'},
 {q:'Which sequence best represents the main high-voltage path in a conventional teaching model?',options:['Line compensation → autotransformer → timer/control → step-up transformer → rectification → tube','Line compensation → filament transformer → rotor → rectification → tube','Autotransformer → focusing cup → step-down transformer → tube','Rectification → autotransformer → timer → filament → anode'],answer:0,rationale:'This sequence traces voltage selection and timing into high-voltage transformation, rectification, and finally the tube.'},
 {q:'What is the focusing cup doing while tube current is flowing?',options:['Electrostatically narrowing the electron cloud toward the focal spot','Stepping voltage up to kilovoltage','Converting AC to DC','Spinning the anode'],answer:0,rationale:'The negatively charged focusing cup shapes and directs the electron cloud toward the focal spot.'},
 {q:'Which component is on the primary side and is NOT the final source of the tube kilovoltage?',options:['Autotransformer','High-voltage transformer secondary','Rectifier bank','X-ray tube'],answer:0,rationale:'The autotransformer supplies selectable primary voltage; the high-voltage transformer creates the much larger tube potential.'},
 {q:'If the high-voltage step-up transformer failed open, which outcome is most likely?',options:['Filament may still heat but electrons would not be accelerated normally across the tube','The rotor would necessarily spin faster','The image receptor would receive excessive scatter only','The autotransformer would become a rectifier'],answer:0,rationale:'The filament circuit can exist separately, but without high tube potential there is no normal acceleration of electrons to the anode.'},
 {q:'Which statement best distinguishes the filament transformer from the high-voltage transformer?',options:['Filament transformer lowers voltage and raises current; high-voltage transformer raises voltage for tube potential','Both raise voltage, but only one uses AC','Filament transformer selects kVp; high-voltage transformer selects mA','Both are located after rectification and operate on steady DC'],answer:0,rationale:'Their functions are opposite: low voltage/high current for filament heating versus high voltage for tube potential.'},
 {q:'The stator and rotor belong to which functional system?',options:['Rotating-anode induction motor','Filament current selection','High-voltage rectification','AEC chamber selection'],answer:0,rationale:'The external stator creates a rotating magnetic field that drives the internal rotor and anode.'},
 {q:'Which event most directly follows thermionic emission during a normal exposure?',options:['Electrons in the space-charge cloud are accelerated toward the positive anode when tube potential is applied','Rectifiers heat the filament','The detector converts light to x-rays','The autotransformer emits electrons'],answer:0,rationale:'Thermionic emission supplies electrons; the applied tube potential then accelerates them across the vacuum.'},
 {q:'A technologist increases selected kVp. Which circuit action most directly changes before the step-up transformer?',options:['A different autotransformer tap/primary voltage is selected','The focusing cup becomes positive','The rectifier changes to a step-down transformer','The rotor reverses direction'],answer:0,rationale:'kVp selection changes the voltage supplied to the primary of the high-voltage transformer through the autotransformer/control system.'},
 {q:'Why can a transformer not operate from a perfectly steady DC input?',options:['Transformer action requires changing magnetic flux','DC has too much frequency','The filament would become positive','Rectifiers only work with DC'],answer:0,rationale:'Electromagnetic induction in a transformer requires changing magnetic flux, which is produced by changing current.'},
 {q:'Which component controls exposure duration in the main circuit?',options:['Timer/electronic switching system','Focusing cup','Rotor bearing','Grid'],answer:0,rationale:'The timing/control stage determines when and how long the high-voltage exposure circuit is energized.'},
 {q:'Which current is measured in milliamperes during exposure?',options:['Tube current from cathode to anode','Filament-heating current only','Line current entering the room','Stator current only'],answer:0,rationale:'Tube current represents the rate of electron flow across the x-ray tube and is expressed in mA.'},
 {q:'A filament-current increase is most directly intended to change:',options:['Number of electrons available for tube current','Maximum photon energy','Rectifier polarity','Anode angle'],answer:0,rationale:'Greater filament heating increases thermionic emission and electron availability, which supports higher tube mA.'},
 {q:'Which component is inside the tube envelope?',options:['Cathode focusing cup','Autotransformer','Line compensator','High-voltage generator cabinet'],answer:0,rationale:'The filament and focusing cup form the cathode assembly inside the evacuated x-ray tube.'},
 {q:'What is the immediate electrical role of the high-voltage transformer secondary?',options:['Provide a large potential difference across the tube circuit','Heat the filament directly with low voltage','Select AEC chambers','Store the digital image'],answer:0,rationale:'The secondary produces the high potential that accelerates electrons from cathode to anode.'},
 {q:'In the circuit-learning diagram, why is the filament branch shown separately from the high-voltage pathway?',options:['It performs a different function: low-voltage, high-current filament heating rather than tube-potential generation','It operates only after the exposure has ended','It is part of the detector rather than the generator','It carries scattered x-ray photons'],answer:0,rationale:'The branches are coordinated but electrically distinct in function: electron supply versus electron acceleration.'}
].map(x=>({...x,category:'Radiation Physics',explanation:x.rationale}));
